export const HISTORY_STORE='zl-real-forward-history-v1';
const labels={text:'文本',image:'图片',caption:'图文',video:'视频',file:'文件',contact:'名片'};
export function readHistory(){try{const v=JSON.parse(localStorage.getItem(HISTORY_STORE)||'[]');return Array.isArray(v)?v:[]}catch{return []}}
export function writeTask(task){const all=readHistory().filter(t=>t.id!==task.id);all.unshift(task);localStorage.setItem(HISTORY_STORE,JSON.stringify(all.slice(0,100)))}
export function taskStats(t){const rs=t.results||[];return {total:rs.length,submitted:rs.filter(r=>r.state==='submitted').length,failed:rs.filter(r=>r.state==='failed').length,done:rs.filter(r=>['submitted','failed','cancelled'].includes(r.state)).length}}
export function taskState(t){if(t.state==='running')return 'interrupted';if(t.results?.some(r=>r.state==='failed'))return 'failed';if(t.results?.some(r=>r.state==='cancelled'))return 'cancelled';return 'finished'}
const states={interrupted:'中断 / 待核对',finished:'已完成',failed:'有失败',cancelled:'已停止'};
const E=(tag,text,cls='')=>{const e=document.createElement(tag);e.className=cls;if(text!==undefined)e.textContent=text;return e};
const B=(text,fn)=>{const b=E('button',text,'button quiet');b.type='button';b.onclick=fn;return b};
const date=v=>v?new Date(v).toLocaleString():'—';
export function renderHistory(host,{newTask,repeat,api}){
 let page=1,size=10,tab='send',filters={term:'',state:'',start:'',end:''};
 host.replaceChildren();const tabs=E('div',undefined,'nt-history-tabs'),toolbar=E('form',undefined,'nt-history-toolbar'),tableHost=E('div',undefined,'nt-table-scroll'),pager=E('div',undefined,'nt-pagination'),detail=E('section',undefined,'nt-task-detail');detail.hidden=true;
 const term=E('input');term.placeholder='搜索消息内容';const status=E('select');for(const [v,l] of [['','全部'],...Object.entries(states)]){const o=E('option',l);o.value=v;status.append(o)}const start=E('input'),end=E('input');start.type=end.type='date';start.title='开始日期';end.title='结束日期';
 toolbar.append(term,status,start,E('span','至'),end,B('搜索',()=>{filters={term:term.value.toLowerCase(),state:status.value,start:start.value,end:end.value};page=1;draw()}),B('重置',()=>{term.value=status.value=start.value=end.value='';filters={term:'',state:'',start:'',end:''};page=1;draw()}),B('清空记录',()=>{if(!confirm('清空本机全部转发和撤回记录？不会删除 WhatsApp 消息。'))return;localStorage.removeItem(HISTORY_STORE);draw()}),B('新建转发',newTask));toolbar.onsubmit=e=>{e.preventDefault();toolbar.querySelector('button').click()};
 for(const [key,label] of [['send','发送记录'],['revoke','撤回记录']]){const b=B(label,()=>{tab=key;page=1;detail.hidden=true;draw()});b.dataset.tab=key;tabs.append(b)}
 host.append(tabs,toolbar,tableHost,detail,pager);
 function info(t){detail.hidden=false;detail.replaceChildren(E('h3','任务详情 · '+date(t.createdAt)),E('p',t.content?.text||t.content?.filename||t.content?.name||'旧记录未保存消息内容'),B('关闭详情',()=>detail.hidden=true));for(const r of t.results||[]){detail.append(E('p',r.name+'：'+({submitted:'已提交（送达以 WhatsApp 回执为准）',failed:'失败',cancelled:'已停止',pending:'未提交',submitting:'结果待核对'}[r.state]||r.state)+(r.error?' · '+r.error:'')+(r.revoke?'；撤回：'+r.revoke.state+(r.revoke.error?' · '+r.revoke.error:''):'')))}}
 async function revoke(t,b){if(!confirm('撤回此任务中已提交的消息？WhatsApp 会检查撤回期限和权限。'))return;host.querySelectorAll('button').forEach(x=>x.disabled=true);for(const r of t.results||[]){if(r.state!=='submitted'||!r.messageId||r.revoke?.state==='已提交')continue;try{await api.whatsAppAction({accountId:t.accountId,action:'revoke',chatId:r.id,messageId:r.messageId});r.revoke={state:'已提交',at:Date.now()}}catch(e){r.revoke={state:'失败',error:e.message,at:Date.now()}}writeTask(t)}host.querySelectorAll('button').forEach(x=>x.disabled=false);draw();info(t)}
 function draw(){tabs.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.tab===tab)));const tasks=readHistory().filter(t=>{if(tab==='revoke'&&!t.results?.some(r=>r.revoke))return false;const summary=[t.content?.text,t.content?.filename,t.content?.name,labels[t.type],...(t.results||[]).map(r=>r.name)].join(' ').toLowerCase();return summary.includes(filters.term)&&(!filters.state||taskState(t)===filters.state)&&(!filters.start||t.createdAt>=new Date(filters.start+'T00:00:00').getTime())&&(!filters.end||t.createdAt<new Date(filters.end+'T23:59:59.999').getTime())});const pages=Math.max(1,Math.ceil(tasks.length/size));page=Math.min(page,pages);tableHost.replaceChildren();const table=E('table',undefined,'nt-history-table'),head=E('thead'),tr=E('tr');for(const h of ['发送内容','状态','发送方式','发送进度','消息发送策略','发送时间','结束时间','操作'])tr.append(E('th',h));head.append(tr);table.append(head);const body=E('tbody');for(const t of tasks.slice((page-1)*size,page*size)){const row=E('tr'),s=taskStats(t);row.append(E('td',t.content?.text||t.content?.filename||t.content?.name||labels[t.type]||t.type),E('td',tab==='revoke'?(t.results.some(r=>r.revoke?.state==='失败')?'撤回有失败':'撤回已提交'):states[taskState(t)]),E('td','立即发送'));const progress=E('td'),bar=E('progress');bar.max=s.total||1;bar.value=s.done;progress.append(bar,E('div',`已提交 ${s.submitted} · 失败 ${s.failed} · 共 ${s.total}`));row.append(progress,E('td','跳过失败，继续发送'),E('td',date(t.createdAt)),E('td',date(t.finishedAt)));const actions=E('td');actions.append(B('详情',()=>info(t)),B('再发一条',()=>repeat(t)));const more=E('details'),summary=E('summary','更多');more.append(summary);const rb=B('撤回消息',()=>revoke(t,rb));rb.disabled=!t.results?.some(r=>r.state==='submitted'&&r.messageId&&r.revoke?.state!=='已提交');more.append(rb,B('删除记录',()=>{if(!confirm('仅删除这条本机记录？不会删除 WhatsApp 消息。'))return;localStorage.setItem(HISTORY_STORE,JSON.stringify(readHistory().filter(v=>v.id!==t.id)));draw()}));actions.append(more);row.append(actions);body.append(row)}table.append(body);tableHost.append(table);if(!tasks.length)tableHost.append(E('p','暂无匹配记录','gm-empty'));pager.replaceChildren(E('span',`共 ${tasks.length} 条`));const prev=B('上一页',()=>{page--;draw()}),next=B('下一页',()=>{page++;draw()});prev.disabled=page===1;next.disabled=page===pages;const per=E('select');for(const n of [10,20,50]){const o=E('option',n+' 条/页');o.value=n;per.append(o)}per.value=size;per.onchange=()=>{size=Number(per.value);page=1;draw()};pager.append(prev,E('span',`${page} / ${pages}`),next,per)}draw();
}
